CREATE TABLE market_execution_holding_movements (execution_key TEXT NOT NULL, party_role TEXT NOT NULL CHECK (party_role IN ('buyer', 'seller')), user_id TEXT NOT NULL, inventory_type TEXT NOT NULL CHECK (inventory_type IN ('user_asset', 'treasury_bond')), signed_quantity BIGINT NOT NULL CHECK (CASE WHEN CAST(PG_TYPEOF(signed_quantity) AS TEXT) IN ('bigint', 'integer') THEN 'integer' WHEN CAST(PG_TYPEOF(signed_quantity) AS TEXT) IN ('double precision', 'numeric') THEN 'real' ELSE 'text' END = 'integer'), PRIMARY KEY (execution_key, party_role), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_execution_journal_baselines (execution_key TEXT PRIMARY KEY, captured_epoch BIGINT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_execution_order_baselines_v2 (order_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, baseline_filled_quantity BIGINT NOT NULL CHECK (baseline_filled_quantity >= 0), baseline_execution_quantity BIGINT NOT NULL CHECK (baseline_execution_quantity >= 0), captured_epoch BIGINT NOT NULL);
CREATE TABLE market_execution_wallet_links (execution_key TEXT NOT NULL, wallet_entry_id BIGINT NOT NULL, PRIMARY KEY (execution_key, wallet_entry_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_factor_state (key TEXT PRIMARY KEY, last_epoch BIGINT NOT NULL, current_factor DOUBLE PRECISION NOT NULL CHECK (ABS(current_factor) < 1.0e308), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_future_expiry_prices (product_code TEXT PRIMARY KEY, underlying_code TEXT NOT NULL, maturity_epoch BIGINT NOT NULL, price DECIMAL NOT NULL CHECK (price > 0) CHECK ((price IS NULL OR (ABS(price) < CAST('1000000000000000000000000' AS DECIMAL)))), recorded_epoch BIGINT NOT NULL, is_final BIGINT NOT NULL DEFAULT 0 CHECK (is_final IN (0, 1)), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_last_trade (asset_code TEXT PRIMARY KEY, price DECIMAL NOT NULL CHECK (price > 0) CHECK ((price IS NULL OR (ABS(price) < CAST('1000000000000000000000000' AS DECIMAL)))), recorded_epoch BIGINT NOT NULL, trade_id BIGINT NOT NULL, price_minor_units DECIMAL NOT NULL DEFAULT 0 CHECK ((price_minor_units IS NULL OR (ABS(price_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND price_minor_units = TRUNC(price_minor_units)))), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_order_wallet_baselines (order_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, captured_epoch BIGINT NOT NULL);
CREATE TABLE market_order_wallet_links (order_id BIGINT NOT NULL, wallet_entry_id BIGINT NOT NULL, PRIMARY KEY (order_id, wallet_entry_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_order_wallet_migrations (migration_key TEXT PRIMARY KEY, applied_epoch BIGINT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE "market_orders" (order_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL, asset_code TEXT NOT NULL, side TEXT NOT NULL CHECK (side IN ('buy', 'sell')), limit_price DECIMAL NOT NULL CHECK (limit_price > 0) CHECK ((limit_price IS NULL OR (ABS(limit_price) < CAST('1000000000000000000000000' AS DECIMAL)))), quantity BIGINT NOT NULL CHECK (quantity > 0), remaining_quantity BIGINT NOT NULL CHECK (remaining_quantity >= 0), reserved_cash DECIMAL NOT NULL DEFAULT 0 CHECK ((reserved_cash IS NULL OR (ABS(reserved_cash) < CAST('1000000000000000000000000' AS DECIMAL)))), funding_account TEXT, status TEXT NOT NULL DEFAULT 'open', created_epoch BIGINT NOT NULL, updated_epoch BIGINT NOT NULL, filled_quantity BIGINT NOT NULL DEFAULT 0, order_kind TEXT NOT NULL DEFAULT 'asset', option_order_type TEXT, quote_currency TEXT, fractional_order BIGINT NOT NULL DEFAULT 0 CHECK (fractional_order IN (0, 1)), reserved_cash_units DECIMAL NOT NULL DEFAULT 0 CHECK (reserved_cash_units >= 0) CHECK ((reserved_cash_units IS NULL OR (ABS(reserved_cash_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND reserved_cash_units = TRUNC(reserved_cash_units)))), executed_value_units DECIMAL NOT NULL DEFAULT 0 CHECK (executed_value_units >= 0) CHECK ((executed_value_units IS NULL OR (ABS(executed_value_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND executed_value_units = TRUNC(executed_value_units)))), activation_epoch BIGINT, scheduled_reason TEXT, reserved_cash_minor_units DECIMAL NOT NULL DEFAULT 0 CHECK ((reserved_cash_minor_units IS NULL OR (ABS(reserved_cash_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND reserved_cash_minor_units = TRUNC(reserved_cash_minor_units)))), limit_price_minor_units DECIMAL NOT NULL DEFAULT 0 CHECK ((limit_price_minor_units IS NULL OR (ABS(limit_price_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND limit_price_minor_units = TRUNC(limit_price_minor_units)))), limit_price_decimal_places BIGINT);
CREATE TABLE market_price_gap_fills (asset_code TEXT NOT NULL, start_epoch BIGINT NOT NULL, end_epoch BIGINT NOT NULL, points BIGINT NOT NULL, filled_epoch BIGINT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_price_history (history_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_code TEXT NOT NULL, price DECIMAL NOT NULL CHECK ((price IS NULL OR (ABS(price) < CAST('1000000000000000000000000' AS DECIMAL)))), recorded_epoch BIGINT NOT NULL, "price_minor_units" DECIMAL NOT NULL DEFAULT 0 CHECK (("price_minor_units" IS NULL OR (ABS("price_minor_units") < CAST('1000000000000000000000000000000' AS DECIMAL) AND "price_minor_units" = TRUNC("price_minor_units")))), UNIQUE (asset_code, recorded_epoch));
CREATE TABLE market_quote_overrides (asset_code TEXT PRIMARY KEY, price DECIMAL NOT NULL CHECK (price > 0) CHECK ((price IS NULL OR (ABS(price) < CAST('1000000000000000000000000' AS DECIMAL)))), updated_epoch BIGINT NOT NULL, source TEXT NOT NULL DEFAULT 'event', rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_rate_curve (nationality TEXT NOT NULL, benchmark_key TEXT NOT NULL CHECK (benchmark_key IN ('funding', 'bank_bond', 'treasury')), tenor_days BIGINT NOT NULL CHECK (tenor_days > 0), annual_rate DOUBLE PRECISION NOT NULL CHECK (annual_rate BETWEEN -100 AND 100), pass_through DOUBLE PRECISION NOT NULL DEFAULT 0.75 CHECK (pass_through BETWEEN 0 AND 2), updated_epoch DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY (nationality, benchmark_key, tenor_days), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_rate_curve_history (nationality TEXT NOT NULL, benchmark_key TEXT NOT NULL, tenor_days BIGINT NOT NULL, annual_rate DOUBLE PRECISION NOT NULL CHECK (annual_rate BETWEEN -100 AND 100), effective_epoch DOUBLE PRECISION NOT NULL, changed_by TEXT NOT NULL DEFAULT 'system', PRIMARY KEY (nationality, benchmark_key, tenor_days, effective_epoch), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_rate_curve_history_events (event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, operation TEXT NOT NULL CHECK (operation IN ('insert', 'update', 'delete', 'replace')), nationality TEXT NOT NULL, benchmark_key TEXT NOT NULL, tenor_days BIGINT NOT NULL, before_rate DOUBLE PRECISION, after_rate DOUBLE PRECISION, before_epoch DOUBLE PRECISION, after_epoch DOUBLE PRECISION, before_actor TEXT, after_actor TEXT, recorded_epoch DOUBLE PRECISION NOT NULL);
CREATE TABLE market_rate_pressure (nationality TEXT NOT NULL, benchmark_key TEXT NOT NULL CHECK (benchmark_key IN ('funding', 'bank_bond', 'treasury')), adjustment DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (adjustment BETWEEN -20 AND 20), updated_epoch DOUBLE PRECISION NOT NULL, PRIMARY KEY (nationality, benchmark_key), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_rate_pressure_history (nationality TEXT NOT NULL, benchmark_key TEXT NOT NULL, adjustment DOUBLE PRECISION NOT NULL CHECK (adjustment BETWEEN -20 AND 20), effective_epoch DOUBLE PRECISION NOT NULL, PRIMARY KEY (nationality, benchmark_key, effective_epoch), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_simulation_state (asset_code TEXT PRIMARY KEY, variance DOUBLE PRECISION NOT NULL CHECK (variance >= 0 AND variance < 1.0e308), innovation DOUBLE PRECISION NOT NULL CHECK (ABS(innovation) < 1.0e308), latent_price DECIMAL NOT NULL CHECK (latent_price >= 1 AND latent_price <= 1000000000000000000000000) CHECK ((latent_price IS NULL OR (ABS(latent_price) < CAST('1000000000000000000000000' AS DECIMAL)))), last_epoch BIGINT NOT NULL, last_display_price DECIMAL NOT NULL CHECK (last_display_price > 0) CHECK ((last_display_price IS NULL OR (ABS(last_display_price) < CAST('1000000000000000000000000' AS DECIMAL)))), event_id BIGINT, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE market_trade_history (trade_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_code TEXT NOT NULL, side TEXT NOT NULL CHECK (side IN ('buy', 'sell')), quantity DOUBLE PRECISION NOT NULL CHECK (quantity > 0), price DECIMAL NOT NULL CHECK (price > 0) CHECK ((price IS NULL OR (ABS(price) < CAST('1000000000000000000000000' AS DECIMAL)))), recorded_epoch BIGINT NOT NULL, price_minor_units DECIMAL NOT NULL DEFAULT 0 CHECK ((price_minor_units IS NULL OR (ABS(price_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND price_minor_units = TRUNC(price_minor_units)))));
CREATE TABLE naturalization_requests (request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL, from_nationality TEXT NOT NULL, to_nationality TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')), requested_epoch DOUBLE PRECISION NOT NULL, decided_by TEXT, decided_epoch DOUBLE PRECISION, note TEXT);
CREATE TABLE option_audit_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1), through_order_id BIGINT NOT NULL);
CREATE TABLE option_collateral_cash_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1), through_contract_id BIGINT NOT NULL);
CREATE TABLE option_collateral_cash_events (event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, contract_id BIGINT NOT NULL, collateral_id BIGINT NOT NULL, writer_id TEXT NOT NULL, movement TEXT NOT NULL CHECK (movement IN ('deposit', 'release')), currency_code TEXT NOT NULL, decimal_places BIGINT NOT NULL CHECK (decimal_places = 0), amount_minor_units DECIMAL NOT NULL CHECK (amount_minor_units > 0) CHECK ((amount_minor_units IS NULL OR (ABS(amount_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND amount_minor_units = TRUNC(amount_minor_units)))), wallet_entry_id BIGINT NOT NULL UNIQUE, journal_entry_id BIGINT NOT NULL UNIQUE, recorded_epoch BIGINT NOT NULL);
CREATE TABLE option_collateral_cash_lots (collateral_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_id BIGINT NOT NULL, writer_id TEXT NOT NULL, account_number TEXT, amount DECIMAL NOT NULL CHECK (amount > 0) CHECK ((amount IS NULL OR (ABS(amount) < CAST('1000000000000000000000000' AS DECIMAL)))));
CREATE TABLE option_collateral_lots (collateral_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_id BIGINT NOT NULL, writer_id TEXT NOT NULL, underlying_code TEXT NOT NULL, account_number TEXT, quantity DECIMAL NOT NULL CHECK (quantity > 0), average_cost DECIMAL NOT NULL DEFAULT 0 CHECK ((average_cost IS NULL OR (ABS(average_cost) < CAST('1000000000000000000000000' AS DECIMAL)))));
CREATE TABLE option_contracts (contract_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_code TEXT UNIQUE, writer_id TEXT NOT NULL, underlying_code TEXT NOT NULL, option_type TEXT NOT NULL CHECK (option_type IN ('call', 'put')), strike_price DECIMAL NOT NULL CHECK (strike_price > 0) CHECK ((strike_price IS NULL OR (ABS(strike_price) < CAST('1000000000000000000000000' AS DECIMAL)))), expiration_epoch BIGINT NOT NULL, implied_volatility DOUBLE PRECISION NOT NULL, issued_contracts BIGINT NOT NULL CHECK (issued_contracts > 0), outstanding_contracts BIGINT NOT NULL DEFAULT 0, collateral_account TEXT, status TEXT NOT NULL DEFAULT 'active', created_epoch BIGINT NOT NULL, settled_epoch BIGINT, quote_currency TEXT NOT NULL DEFAULT 'NWX');
CREATE TABLE option_exercise_asset_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1));
CREATE TABLE option_exercise_asset_baseline (event_key TEXT PRIMARY KEY, reason TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_exercise_asset_movements (event_key TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('collateral', 'seller', 'recipient')), user_id TEXT NOT NULL, asset_code TEXT NOT NULL, quantity TEXT NOT NULL, before_quantity TEXT NOT NULL, after_quantity TEXT NOT NULL, PRIMARY KEY (event_key, role), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_exercise_cash_links (event_key TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('payer', 'recipient')), wallet_entry_id BIGINT UNIQUE, fund_entry_id BIGINT UNIQUE, delta_minor_units DECIMAL NOT NULL CHECK ((delta_minor_units IS NULL OR (ABS(delta_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND delta_minor_units = TRUNC(delta_minor_units)))), CHECK ((wallet_entry_id IS NULL) <> (fund_entry_id IS NULL)), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_exercise_events (event_key TEXT PRIMARY KEY, contract_id BIGINT NOT NULL, contract_code TEXT NOT NULL, option_type TEXT NOT NULL CHECK (option_type IN ('call', 'put')), holder_id TEXT NOT NULL, writer_id TEXT NOT NULL, quantity BIGINT NOT NULL CHECK (quantity > 0), gross_minor_units DECIMAL NOT NULL CHECK (gross_minor_units > 0) CHECK ((gross_minor_units IS NULL OR (ABS(gross_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND gross_minor_units = TRUNC(gross_minor_units)))), tax_minor_units DECIMAL NOT NULL CHECK (tax_minor_units >= 0 AND tax_minor_units <= gross_minor_units) CHECK ((tax_minor_units IS NULL OR (ABS(tax_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND tax_minor_units = TRUNC(tax_minor_units)))), currency_code TEXT NOT NULL, decimal_places BIGINT NOT NULL CHECK (decimal_places = 0), recorded_epoch BIGINT NOT NULL, journal_entry_id BIGINT NOT NULL UNIQUE, UNIQUE (contract_id, holder_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_exercise_link_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1));
CREATE TABLE option_exercise_link_baseline (event_key TEXT PRIMARY KEY, reason TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_order_cash_links (link_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, movement TEXT NOT NULL CHECK (movement IN ('reserve', 'refund')), wallet_entry_id BIGINT UNIQUE, fund_entry_id BIGINT UNIQUE, CHECK ((wallet_entry_id IS NULL) <> (fund_entry_id IS NULL)));
CREATE TABLE option_order_fill_baselines (order_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, filled_quantity BIGINT NOT NULL);
CREATE TABLE option_positions (contract_id BIGINT NOT NULL, user_id TEXT NOT NULL, quantity BIGINT NOT NULL CHECK (quantity > 0), average_premium DECIMAL NOT NULL DEFAULT 0 CHECK ((average_premium IS NULL OR (ABS(average_premium) < CAST('1000000000000000000000000' AS DECIMAL)))), PRIMARY KEY (contract_id, user_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE option_premium_events (event_key TEXT PRIMARY KEY, contract_code TEXT NOT NULL, buy_order_id BIGINT NOT NULL, sell_order_id BIGINT NOT NULL, buyer_id TEXT NOT NULL, seller_id TEXT NOT NULL, quantity BIGINT NOT NULL CHECK (quantity > 0), price_minor_units DECIMAL NOT NULL CHECK (price_minor_units > 0) CHECK ((price_minor_units IS NULL OR (ABS(price_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND price_minor_units = TRUNC(price_minor_units)))), premium_minor_units DECIMAL NOT NULL CHECK (premium_minor_units = (quantity * price_minor_units)) CHECK ((premium_minor_units IS NULL OR (ABS(premium_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND premium_minor_units = TRUNC(premium_minor_units)))), currency_code TEXT NOT NULL, decimal_places BIGINT NOT NULL CHECK (decimal_places = 0), recorded_epoch BIGINT NOT NULL, journal_entry_id BIGINT NOT NULL UNIQUE, wallet_entry_id BIGINT UNIQUE, fund_entry_id BIGINT UNIQUE, CHECK ((wallet_entry_id IS NULL) <> (fund_entry_id IS NULL)), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE organization_group_members (membership_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL, organization_code TEXT NOT NULL, joined_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), left_epoch BIGINT, CHECK (left_epoch IS NULL OR left_epoch >= joined_epoch));
CREATE TABLE organization_groups (group_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, representative_organization_code TEXT, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')), created_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), updated_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)));
CREATE TABLE organization_size_settings (singleton BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton = 1), announcement_seconds BIGINT NOT NULL DEFAULT 0 CHECK (announcement_seconds >= 0), rule_json TEXT NOT NULL DEFAULT '{}', updated_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)));
CREATE TABLE organizations (organization_code TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', industry TEXT NOT NULL DEFAULT '', country_code TEXT, status TEXT NOT NULL DEFAULT 'active', purpose TEXT NOT NULL DEFAULT 'for_profit' CHECK (purpose IN ('for_profit', 'nonprofit')), ownership_type TEXT NOT NULL DEFAULT 'private' CHECK (ownership_type IN ('private', 'national', 'local', 'mixed', 'other')), public_enterprise_type TEXT NOT NULL DEFAULT 'none' CHECK (public_enterprise_type IN ('none', 'public_corporation', 'market_based', 'quasi_market_based', 'other_public')), legal_form TEXT NOT NULL DEFAULT 'corporation', size_override TEXT CHECK (size_override IS NULL OR size_override IN ('sme', 'mid_market', 'large')), size_override_reason TEXT, auto_size TEXT CHECK (auto_size IS NULL OR auto_size IN ('sme', 'mid_market', 'large')), pending_size TEXT CHECK (pending_size IS NULL OR pending_size IN ('sme', 'mid_market', 'large')), size_effective_epoch BIGINT, created_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), updated_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE overdraft_events (event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, account_number TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('draw', 'repay', 'interest')), units BIGINT NOT NULL CHECK (units > 0), epoch DOUBLE PRECISION NOT NULL, posted BIGINT NOT NULL DEFAULT 0);
CREATE TABLE preferred_dividend_claims (claim_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, issuer_code TEXT NOT NULL, asset_code TEXT NOT NULL, distribution_id BIGINT NOT NULL, user_id TEXT NOT NULL, quantity BIGINT NOT NULL CHECK (quantity > 0), gross_amount DECIMAL NOT NULL CHECK (gross_amount > 0) CHECK ((gross_amount IS NULL OR (ABS(gross_amount) < CAST('1000000000000000000000000' AS DECIMAL)))), paid_amount DECIMAL NOT NULL DEFAULT 0 CHECK (paid_amount >= 0 AND paid_amount <= gross_amount) CHECK ((paid_amount IS NULL OR (ABS(paid_amount) < CAST('1000000000000000000000000' AS DECIMAL)))), quote_currency TEXT NOT NULL DEFAULT 'NWX', funding_source TEXT NOT NULL CHECK (funding_source IN ('treasury', 'issuer')), due_epoch BIGINT NOT NULL, created_epoch BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'unpaid' CHECK (status IN ('unpaid', 'partial', 'paid', 'written_off')), UNIQUE (distribution_id, user_id));
CREATE TABLE product_settlements (settlement_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL, product_code TEXT NOT NULL, kind TEXT NOT NULL, quantity BIGINT NOT NULL, gross_amount DECIMAL NOT NULL CHECK ((gross_amount IS NULL OR (ABS(gross_amount) < CAST('1000000000000000000000000' AS DECIMAL)))), tax_amount DECIMAL NOT NULL DEFAULT 0 CHECK ((tax_amount IS NULL OR (ABS(tax_amount) < CAST('1000000000000000000000000' AS DECIMAL)))), recorded_epoch BIGINT NOT NULL);
CREATE TABLE rate_history (history_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, rate_key TEXT NOT NULL CHECK (rate_key IN ('base_rate', 'legal_max_rate')), annual_percent DOUBLE PRECISION NOT NULL, effective_epoch DOUBLE PRECISION NOT NULL, changed_by TEXT NOT NULL, CHECK ((rate_key = 'base_rate' AND annual_percent BETWEEN -100 AND 100) OR (rate_key = 'legal_max_rate' AND annual_percent BETWEEN 0 AND 100)));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE share_issuances (issuance_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_code TEXT NOT NULL, class_name TEXT NOT NULL, share_class TEXT NOT NULL CHECK (share_class IN ('common', 'preferred')), voting_rights_per_share TEXT NOT NULL DEFAULT '1', economic_interest_per_share TEXT NOT NULL DEFAULT '1', rights_json TEXT NOT NULL DEFAULT '{}', created_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), updated_epoch BIGINT NOT NULL DEFAULT (CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)));
CREATE TABLE share_resolution_executions (resolution_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, action_record_id BIGINT NOT NULL UNIQUE, executed_by TEXT NOT NULL, executed_epoch BIGINT NOT NULL);
CREATE TABLE shareholder_meeting_holders (meeting_id BIGINT NOT NULL, user_id TEXT NOT NULL, nickname TEXT NOT NULL, shares DOUBLE PRECISION NOT NULL, attendance TEXT CHECK (attendance IN ('attend', 'absent')), responded_epoch BIGINT, PRIMARY KEY (meeting_id, user_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE shareholder_meeting_items (item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, meeting_id BIGINT NOT NULL, seq BIGINT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '');
CREATE TABLE shareholder_meeting_votes (item_id BIGINT NOT NULL, user_id TEXT NOT NULL, choice TEXT NOT NULL CHECK (choice IN ('for', 'against', 'abstain')), voted_epoch BIGINT NOT NULL, PRIMARY KEY (item_id, user_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE shareholder_meetings (meeting_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_code TEXT NOT NULL, company_name TEXT NOT NULL, convener_id TEXT NOT NULL, convener_name TEXT NOT NULL, place TEXT NOT NULL, meeting_epoch BIGINT NOT NULL, close_epoch BIGINT NOT NULL, closed_epoch BIGINT, created_epoch BIGINT NOT NULL);
CREATE TABLE shareholder_register_dr_entitlements (register_id BIGINT NOT NULL, user_id TEXT NOT NULL, dr_code TEXT NOT NULL, payout_currency TEXT NOT NULL, quantity DOUBLE PRECISION NOT NULL CHECK (quantity > 0), tax_residency TEXT, PRIMARY KEY (register_id, user_id, dr_code), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE shareholder_register_dr_entries (register_id BIGINT NOT NULL, user_id TEXT NOT NULL, payout_currency TEXT NOT NULL, quantity DOUBLE PRECISION NOT NULL CHECK (quantity > 0), PRIMARY KEY (register_id, user_id, payout_currency), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE shareholder_register_entries (register_id BIGINT NOT NULL, user_id TEXT NOT NULL, quantity DOUBLE PRECISION NOT NULL CHECK (quantity > 0), tax_residency TEXT, PRIMARY KEY (register_id, user_id), rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE shareholder_registers (register_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, operation_key TEXT NOT NULL UNIQUE, asset_code TEXT NOT NULL, dividend_kind TEXT NOT NULL CHECK (dividend_kind IN ('regular', 'special')), record_epoch BIGINT NOT NULL, pay_epoch BIGINT NOT NULL, per_share DECIMAL NOT NULL DEFAULT 0 CHECK (per_share >= 0) CHECK ((per_share IS NULL OR (ABS(per_share) < CAST('1000000000000000000000000' AS DECIMAL)))), status TEXT NOT NULL DEFAULT 'closed' CHECK (status IN ('closed', 'paid', 'failed')), actor_id TEXT, note TEXT, created_epoch BIGINT NOT NULL);
CREATE TABLE shareholder_resolutions (resolution_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_code TEXT NOT NULL, ratio BIGINT NOT NULL CHECK (ratio >= 2), decision TEXT NOT NULL CHECK (decision IN ('approved', 'rejected')), meeting_reference TEXT NOT NULL, articles_reference TEXT NOT NULL, par_value_minor_units DECIMAL NOT NULL CHECK ((par_value_minor_units IS NULL OR (ABS(par_value_minor_units) < CAST('1000000000000000000000000000000' AS DECIMAL) AND par_value_minor_units = TRUNC(par_value_minor_units)))), capital_snapshot TEXT NOT NULL, shares_snapshot BIGINT NOT NULL, currency_code TEXT NOT NULL, recorded_by TEXT NOT NULL, recorded_epoch BIGINT NOT NULL);
CREATE TABLE site_feedback (feedback_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('contact', 'report')), title TEXT NOT NULL, body TEXT NOT NULL, discord_id TEXT NOT NULL, email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'read', 'done')), created_epoch BIGINT NOT NULL, handled_by TEXT, handled_epoch BIGINT);
CREATE TABLE swap_contracts (swap_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL, nationality TEXT NOT NULL, currency TEXT NOT NULL, notional DECIMAL NOT NULL CHECK (notional > 0) CHECK ((notional IS NULL OR (ABS(notional) < CAST('1000000000000000000000000' AS DECIMAL)))), side TEXT NOT NULL CHECK (side IN ('pay_fixed', 'receive_fixed')), fixed_rate DOUBLE PRECISION NOT NULL, tenor_days BIGINT NOT NULL CHECK (tenor_days > 0), start_epoch DOUBLE PRECISION NOT NULL, maturity_epoch DOUBLE PRECISION NOT NULL, last_settle_epoch DOUBLE PRECISION NOT NULL, margin DECIMAL NOT NULL DEFAULT 0 CHECK (margin >= 0) CHECK ((margin IS NULL OR (ABS(margin) < CAST('1000000000000000000000000' AS DECIMAL)))), realized DECIMAL NOT NULL DEFAULT 0 CHECK ((realized IS NULL OR (ABS(realized) < CAST('1000000000000000000000000' AS DECIMAL)))), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'matured', 'defaulted')), closed_epoch DOUBLE PRECISION);
CREATE TABLE tax_bank_remittance_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1), through_transaction_id BIGINT NOT NULL CHECK (through_transaction_id >= 0));
CREATE TABLE tax_bank_remittance_links (transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_entry_id BIGINT NOT NULL UNIQUE, settlement_entry_id BIGINT UNIQUE);
CREATE TABLE tax_bank_remittance_quote_activation (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1), through_transaction_id BIGINT NOT NULL CHECK (through_transaction_id >= 0));
CREATE TABLE tax_bank_remittance_quotes (transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_currency TEXT NOT NULL, settlement_currency TEXT NOT NULL, source_places BIGINT NOT NULL, settlement_places BIGINT NOT NULL, rate_numerator TEXT NOT NULL, rate_denominator TEXT NOT NULL);
CREATE TABLE tax_transaction_wallet_baseline_state (singleton_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (singleton_id = 1), through_transaction_id BIGINT NOT NULL CHECK (through_transaction_id >= 0));
